export function verifyAcpDiff(diff, classifications) {
  if (classifications.comparison !== diff.comparison
      || classifications.inputCanonicalSha256?.v1 !== diff.inputs.v1.sha256
      || classifications.inputCanonicalSha256?.v2Preview !== diff.inputs.v2Preview.sha256) {
    throw new Error("ACP reviewed classifications do not match the current schema inputs");
  }
  const definitions = diff.commonDefinitions.definitions;
  const sets = {
    added: diff.definitionSets.added,
    removed: diff.definitionSets.removed,
    documentationOnly: definitions.filter((entry) => entry.classification === "DOCUMENTATION_ONLY").map((entry) => entry.name),
    structural: definitions.filter((entry) => entry.classification === "STRUCTURAL").map((entry) => entry.name),
  };
  for (const [name, names] of Object.entries(sets)) {
    const review = classifications.reviewedSets?.[name];
    const namesSha256 = sha256(Buffer.from(JSON.stringify(names)));
    if (!review || review.count !== names.length || review.namesSha256 !== namesSha256
        || typeof review.category !== "string" || review.category.length === 0) {
      throw new Error(`ACP ${name} changes require an exact reviewed classification`);
    }
  }
  const required = definitions.filter((entry) => entry.directRequired !== null);
  const reviewedRequiredNames = Object.keys(classifications.requiredChanges ?? {}).sort(compare);
  if (required.length !== 19 || JSON.stringify(reviewedRequiredNames) !== JSON.stringify(required.map((entry) => entry.name))) {
    throw new Error(`ACP direct required changes require complete classification; expected ${required.length}, found ${reviewedRequiredNames.length}`);
  }
  for (const entry of required) {
    const review = classifications.requiredChanges[entry.name];
    if (review.category !== entry.directRequired.classification
        || typeof review.rationale !== "string" || review.rationale.length === 0) {
      throw new Error(`ACP required change is unclassified: ${entry.name}`);
    }
  }
  return true;
}
